import anthropic from collections import Counter client = anthropic.Anthropic() def self_consistency_confidence( prompt: str, n_samples: int = 10, temperature: float = 0.7, ) -> tuple[str, float]: """ Sample n_samples completions and return the majority answer with its agreement rate as a confidence score. """ responses = [] for _ in range(n_samples): response = client.messages.create( model="claude-sonnet-4-6", max_tokens=256, temperature=temperature, messages=[{"role": "user", "content": prompt}], ) responses.append(response.content[0].text.strip()) counts = Counter(responses) majority_answer, majority_count = counts.most_common(1)[0] confidence = majority_count / n_samples return majority_answer, confidence def verbalized_confidence(prompt: str, answer: str) -> float: """ Ask the model to self-rate confidence. Treat as a weak signal only — models are systematically overconfident. Use for ranking, not absolute thresholds. """ # User content interpolated here — a crafted prompt can inflate the self-rating. # Never use verbalized confidence as the sole routing gate in adversarial contexts. rating_prompt = ( f"You answered the following question:

" f"Question: {prompt}
" f"Your answer: {answer}

" f"On a scale from 0.0 to 1.0, how confident are you this answer is correct? " f"Reply with only a decimal number." ) response = client.messages.create( model="claude-haiku-4-5-20251001", max_tokens=10, messages=[{"role": "user", "content": rating_prompt}], ) try: score = float(response.content[0].text.strip()) return max(0.0, min(1.0, score)) # clamp — out-of-range value bypasses routing thresholds except ValueError: return 0.5 # default to uncertain on parse failure def confidence_gated_response( prompt: str, high_threshold: float = 0.8, low_threshold: float = 0.4, n_samples: int = 7, ) -> dict: """ Returns the answer along with routing recommendation based on confidence. """ answer, confidence = self_consistency_confidence(prompt, n_samples=n_samples) if confidence >= high_threshold: routing = "serve" elif confidence >= low_threshold: routing = "review" # show to user but flag for spot-check else: routing = "escalate" # don't serve — route to human or fallback return { "answer": answer, "confidence": confidence, "routing": routing, "samples": n_samples, } # Calibration measurement (offline, on a labeled validation set) def expected_calibration_error( predictions: list[tuple[float, bool]], # (confidence, correct) n_bins: int = 10, ) -> float: """Compute ECE — lower is better calibrated. 0.0 = perfect calibration.""" bins = [[] for _ in range(n_bins)] for confidence, correct in predictions: bin_idx = min(int(confidence * n_bins), n_bins - 1) bins[bin_idx].append((confidence, correct)) ece = 0.0 n_total = len(predictions) for bin_data in bins: if not bin_data: continue avg_confidence = sum(c for c, _ in bin_data) / len(bin_data) accuracy = sum(1 for _, correct in bin_data if correct) / len(bin_data) ece += (len(bin_data) / n_total) * abs(avg_confidence - accuracy) return ece For factual QA, self-consistency across 7 samples gives a meaningful confidence signal. An answer that 6 of 7 samples agree on (confidence = 0.86) should be served. An answer only 2 of 7 agree on (confidence = 0.29) should escalate. Note: 7 samples means 7 API calls — factor the N× cost into your routing threshold decisions. Running self-consistency on every request may be unacceptable for latency-sensitive applications; consider reserving it for high-stakes queries or running it offline to build a calibration dataset.

import anthropic from dataclasses import dataclass from enum import Enum client = anthropic.Anthropic() class DegradationLevel(Enum): FULL = "full" # normal AI response REDUCED = "reduced" # simplified model / prompt STATIC = "static" # pre-approved fallback content ESCALATED = "escalated" # human review queue @dataclass class DegradedResponse: content: str level: DegradationLevel reason: str STATIC_FALLBACKS = { "billing": "For billing questions, contact support@example.com or call 1-800-555-0100.", "legal": "We can't provide legal advice. Please consult a qualified attorney.", "medical": "Please consult a healthcare professional for medical guidance.", "default": "I'm unable to answer this confidently right now. A team member will follow up.", } def estimate_confidence(response_text: str, prompt: str) -> float: """Use a lightweight LLM-as-judge to score response confidence (0.0–1.0).""" # User content is interpolated here — a crafted prompt can manipulate the judge's # score (prompt injection). Treat this score as a soft signal, not a hard gate. judge_response = client.messages.create( model="claude-haiku-4-5-20251001", max_tokens=10, messages=[{ "role": "user", "content": ( f"Rate from 0.0 to 1.0 how confident and accurate this response is.
" f"Question: {prompt}
Response: {response_text}
" f"Reply with only a number between 0.0 and 1.0." ), }], ) try: score = float(judge_response.content[0].text.strip()) return max(0.0, min(1.0, score)) # clamp — out-of-range value bypasses routing threshold except ValueError: return 0.0 # unparseable → treat as low confidence def enqueue_for_human_review(prompt: str, context: dict) -> str: """Submit to human review queue. Returns a ticket ID.""" # In production: insert to DB, Slack webhook, Zendesk, etc. ticket_id = f"ESC-{hash(prompt) % 100000:05d}" # Never log prompt content to stdout — use a secured audit log for sensitive content print(f"[ESCALATION] Ticket {ticket_id} queued (topic: {context.get('topic', 'unknown')})") return ticket_id def respond_with_degradation( prompt: str, topic: str = "default", confidence_threshold: float = 0.7, allow_escalation: bool = True, ) -> DegradedResponse: # Level 1: try primary model try: primary = client.messages.create( model="claude-sonnet-4-6", max_tokens=512, messages=[{"role": "user", "content": prompt}], ) text = primary.content[0].text confidence = estimate_confidence(text, prompt) if confidence >= confidence_threshold: return DegradedResponse(text, DegradationLevel.FULL, "high confidence") # Level 2: try simplified prompt with reduced scope simplified = client.messages.create( model="claude-haiku-4-5-20251001", max_tokens=256, system="Answer only if you are highly certain. Otherwise say 'I don't know.'", messages=[{"role": "user", "content": prompt}], ) reduced_text = simplified.content[0].text if "i don't know" not in reduced_text.lower(): return DegradedResponse(reduced_text, DegradationLevel.REDUCED, "low primary confidence") except Exception: pass # fall through to static/escalation # Level 3: static fallback fallback = STATIC_FALLBACKS.get(topic, STATIC_FALLBACKS["default"]) if allow_escalation: # Level 4: escalate and acknowledge ticket_id = enqueue_for_human_review(prompt, {"topic": topic}) return DegradedResponse( f"{fallback}

Your request has been escalated (ref: {ticket_id}).", DegradationLevel.ESCALATED, "below confidence threshold — human review queued", ) return DegradedResponse(fallback, DegradationLevel.STATIC, "below confidence threshold") The system tries the primary model, checks confidence, attempts a more conservative simplified prompt, then falls back to static content and human escalation. The caller always gets a DegradedResponse — never an unhandled exception.
